//! The program's logic must match the chain-agnostic core exactly. These tests read the golden
//! vectors generated by `packages/core` (`pnpm --filter @agent-call-markets/core gen-vectors`).

use call_markets::logic::rule::{DEFAULT_PARAMS, Observation, Outcome, Params, decide_outcome};
use call_markets::logic::seal::{CallFields, SEAL_DOMAIN_PREFIX, commitment, encode_preimage};
use serde::Deserialize;

const SEAL_V1: &str = include_str!("../../../packages/core/test-vectors/seal-v1.json");
const SETTLEMENT_V1: &str = include_str!("../../../packages/core/test-vectors/settlement-v1.json");

fn hex32(s: &str) -> [u8; 32] {
    let v = hex(s);
    v.try_into().expect("32 bytes")
}

fn hex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2), "odd hex length");
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex digit"))
        .collect()
}

fn to_hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SealFile {
    domain_prefix: String,
    preimage_length: usize,
    valid: Vec<SealCase>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SealCase {
    name: String,
    call: SealCall,
    salt: String,
    preimage: String,
    commitment: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SealCall {
    version: u8,
    agent: String,
    feed_id: String,
    direction: u8,
    level_mantissa: String,
    level_expo: i32,
    expiry_ts: String,
}

#[test]
fn seal_v1_vectors_encode_and_hash_identically() {
    let file: SealFile = serde_json::from_str(SEAL_V1).expect("seal vectors parse");
    assert_eq!(to_hex(SEAL_DOMAIN_PREFIX), file.domain_prefix);
    assert!(!file.valid.is_empty());
    for case in &file.valid {
        assert_eq!(case.call.version, 1, "{}", case.name);
        let fields = CallFields {
            agent: hex32(&case.call.agent),
            feed_id: hex32(&case.call.feed_id),
            direction: case.call.direction,
            level_mantissa: case.call.level_mantissa.parse().expect("i64"),
            level_expo: case.call.level_expo,
            expiry_ts: case.call.expiry_ts.parse().expect("i64"),
        };
        let salt = hex32(&case.salt);
        let preimage = encode_preimage(&fields, &salt);
        assert_eq!(preimage.len(), file.preimage_length);
        assert_eq!(to_hex(&preimage), case.preimage, "preimage {}", case.name);
        assert_eq!(
            to_hex(&commitment(&fields, &salt)),
            case.commitment,
            "commitment {}",
            case.name
        );
    }
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SettlementFile {
    params: SettlementParams,
    cases: Vec<SettlementCase>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SettlementParams {
    settle_window_secs: String,
    max_conf_bps: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SettlementCase {
    name: String,
    rust_skip: Option<String>,
    call: SettlementCall,
    observation: SettlementObs,
    expected: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SettlementCall {
    feed_id: String,
    direction: u8,
    level_mantissa: String,
    level_expo: i32,
    expiry_ts: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SettlementObs {
    feed_id: String,
    price: String,
    conf: String,
    expo: i32,
    publish_time: String,
    prev_publish_time: String,
}

#[test]
fn settlement_vectors_decide_identically() {
    let file: SettlementFile =
        serde_json::from_str(SETTLEMENT_V1).expect("settlement vectors parse");
    let params = Params {
        settle_window_secs: file.params.settle_window_secs.parse().expect("i64"),
        max_conf_bps: file.params.max_conf_bps.parse().expect("u16"),
        ..DEFAULT_PARAMS
    };
    assert_eq!(params, DEFAULT_PARAMS, "vectors use the default params");

    let mut checked = 0;
    for case in &file.cases {
        if let Some(reason) = &case.rust_skip {
            // Only cases that cannot be expressed on-chain are skipped, each with a reason.
            assert!(!reason.is_empty(), "{}: skip needs a reason", case.name);
            continue;
        }
        let call = CallFields {
            agent: [0x11; 32],
            feed_id: hex32(&case.call.feed_id),
            direction: case.call.direction,
            level_mantissa: case.call.level_mantissa.parse().expect("i64"),
            level_expo: case.call.level_expo,
            expiry_ts: case.call.expiry_ts.parse().expect("i64"),
        };
        let obs = Observation {
            feed_id: hex32(&case.observation.feed_id),
            price: case.observation.price.parse().expect("i64"),
            conf: case.observation.conf.parse().expect("u64"),
            expo: case.observation.expo,
            publish_time: case.observation.publish_time.parse().expect("i64"),
            prev_publish_time: case.observation.prev_publish_time.parse().expect("i64"),
        };
        let got = match decide_outcome(&call, &obs, &params) {
            Ok(Outcome::Hit) => "HIT",
            Ok(Outcome::Miss) => "MISS",
            Err(e) => e.core_code(),
        };
        assert_eq!(got, case.expected, "case {}", case.name);
        checked += 1;
    }
    assert!(
        checked >= 30,
        "expected the bulk of the vectors to run, ran {checked}"
    );
}
